/**
 * API 응답 전체(JSON)에서 columns/data를 추출해 바로 마크다운 테이블로 변환
 * @param apiResponse 서버에서 받은 전체 응답 객체
 * @returns 마크다운 테이블 문자열
 */
export function priceApiResponseToMarkdownTable(apiResponse: any): string {
	if (!apiResponse?.data) return '';
	// columns: 2차 배열일 수 있음
	const columns = Array.isArray(apiResponse.data.columns)
		? (Array.isArray(apiResponse.data.columns[0]) ? apiResponse.data.columns[0] : apiResponse.data.columns)
		: [];
	const data = Array.isArray(apiResponse.data.data) ? apiResponse.data.data : [];
	if (!columns.length || !data.length) return '';
	return priceDataToMarkdownTable(columns, data);
}

/**
 * JSON 단가표 데이터를 마크다운 테이블 문자열로 변환
 * @param columns 컬럼 정의 배열 (ex: [{name: '분류', ...}, ...])
 * @param data 데이터 배열 (ex: [{분류: '...', 항목: '...', ...}, ...])
 * @returns 마크다운 테이블 문자열
 */
export function priceDataToMarkdownTable(columns: { name: string }[], data: Record<string, any>[]): string {
	if (!columns?.length || !data?.length) return '';
	// 헤더
	const headers = columns.map(col => col.name);
	const headerLine = `| ${headers.join(' | ')} |`;
	const separatorLine = `|${headers.map(() => ' --- ').join('|')}|`;
	// 데이터
	const rows = data.map(row =>
		`| ${headers.map(h => (row[h] !== undefined ? String(row[h]) : '')).join(' | ')} |`
	);
	return [headerLine, separatorLine, ...rows].join('\n');
}

